  struct StateG s1, s2;
  init(&s1);
  init(&s2);
  
  // a10, 10 words: the address is public
  s1.regs[10] = 0;
  s2.regs[10] = 0;
  // a11, 10 words: the address is public
  s1.regs[11] = 40;
  s2.regs[11] = 40;
  // a12, 10 words: the address is public
