  s2.regs[12] = 80;
  // a13, 10 words: the address is public
  s1.regs[13] = 120;
  s2.regs[13] = 120;
  // its contents, public: the same draw in both states
  for (int i=0; i<10; i++) {
    int v = bounded(0, 1);
    s1.mem[20 + i] = v;
    s2.mem[20 + i] = v;
  }
  // its contents, public: the same draw in both states
  for (int i=0; i<10; i++) {
    int v = bounded(0, 1);
    s1.mem[30 + i] = v;
    s2.mem[30 + i] = v;
  }
  
